/**
 * `arenaParamsRead.ts` — the app's read of the escrow's **terms** from the relay.
 *
 * ## Why this module exists
 *
 * The escrow terms (the committee's FROST group key, the mint, its keyset, the
 * network's window/duration bounds, the proof cap and the threshold) used to be
 * read over HTTP from the auctions backend (`GET /api/auctions/config`). That
 * was the **last** client→backend HTTP reader, and it was wrong for a reason
 * that only became load-bearing once the chain grew a committed params event:
 *
 * - **`group_key` is regenerated by every `arena init`.** A hardcoded (or
 *   stale-cached) committee key locks an escrow to a key the deployment cannot
 *   sign for — silently unspendable. The relay is now the only correct source,
 *   and it must be read fresh at the moment a bid is funded.
 *
 * The chain publishes **kind 1448**, schema `arena.params.v1`, on change and on
 * a block cadence, anchored to the same `(height, app_hash)` as the kind-1447
 * commitment published in the same pass. This module reads it with the **same
 * discipline the app already applies to kind-1445 verdicts**
 * (`notes/REPLY-nostr-verdict-contract.md`, `arenaAnchor.ts`,
 * `sdk/commerce/auctions/auctionRead.ts`): a signature that verifies, a schema
 * that matches, a **mandatory** `(height, app_hash)` anchor whose tag copy
 * **agrees** with the content copy, and a signer that is on the committed
 * validator roster. Anything else is refused **by name**, never guessed at.
 *
 * ## The two facts that shape it
 *
 * 1. **`params_version` is not client-recomputable.** It is the sha256 of the Go
 *    `Params` struct's canonical JSON, which a wire client cannot reconstruct.
 *    It is carried here as an **opaque comparison token** — "the terms I hold
 *    are the terms in that app hash" — and is never re-derived from the fields.
 * 2. **The relay carries foreign params events.** `wss://relay.playday.it` holds
 *    short-lived test-chain events at heights 2 and 20 alongside the live
 *    deployment's. The anchor check is therefore **not optional**: the reader
 *    keeps the newest **anchored** reading by height, so a foreign event at a
 *    lower anchored height can never shadow the live one. (A self-consistent
 *    foreign event passes the roster check — it carries its own validator set —
 *    so height, not the roster, is what orders two valid readings.)
 *
 * ## Honesty rule
 *
 * Every term is exposed with **`null` for unknown**. Nothing is defaulted, and
 * nothing is `0`-filled: a missing mint is `null`, not an empty string, and a
 * missing threshold is `null`, not `0`. A consumer that needs a term refuses
 * when it is `null`; it does not invent one.
 *
 * Pure where it can be (`parseArenaParamsEvent`, `selectNewestArenaParams` —
 * no network, no React, no relay import) and I/O only at
 * {@link createWebArenaParamsRead}, exactly as `arenaAuctionRead.ts` splits it.
 */

import type { EventFilter, EventReadContext, EventStorePort, NostrEventLike } from '@sdk/core'
import type { Event } from '@sdk/core/nostr-io'
import { ARENA_PARAMS_KIND, ARENA_PARAMS_SCHEMA } from '@sdk/commerce/auctions/constants'
import { verifyNostrEventSignature } from '@sdk/core/nostr/eventSignature'
import { createWebRelayReadContext } from '@platform/web/sdkNostrIo'

// =========================================================================
// Input — the only fields a parser reads. A `nostr-tools` `NostrEvent`
// (and an `EventReadContext` event) is structurally assignable.
// =========================================================================

export interface ArenaParamsEventLike {
	id: string
	pubkey: string
	kind: number
	created_at: number
	tags: string[][]
	content: string
	sig: string
}

// =========================================================================
// Named refusals
//
// Names, never message strings, so a caller (and a test) can tell one failure
// mode from another on the wire — the discipline `arenaAnchor.ts:39-58` set.
// =========================================================================

export const ARENA_PARAMS_REFUSAL_BAD_KIND = 'arena.params.bad_kind' as const
export const ARENA_PARAMS_REFUSAL_BAD_SIGNATURE = 'arena.params.bad_signature' as const
export const ARENA_PARAMS_REFUSAL_BAD_SCHEMA = 'arena.params.bad_schema' as const
export const ARENA_PARAMS_REFUSAL_BAD_CONTENT = 'arena.params.bad_content' as const
export const ARENA_PARAMS_REFUSAL_UNANCHORED = 'arena.params.unanchored' as const
export const ARENA_PARAMS_REFUSAL_BAD_ANCHOR = 'arena.params.bad_anchor' as const
export const ARENA_PARAMS_REFUSAL_ANCHOR_MISMATCH = 'arena.params.anchor_mismatch' as const
export const ARENA_PARAMS_REFUSAL_SIGNER_NOT_IN_ROSTER = 'arena.params.signer_not_in_roster' as const

export type ArenaParamsRefusalName =
	| typeof ARENA_PARAMS_REFUSAL_BAD_KIND
	| typeof ARENA_PARAMS_REFUSAL_BAD_SIGNATURE
	| typeof ARENA_PARAMS_REFUSAL_BAD_SCHEMA
	| typeof ARENA_PARAMS_REFUSAL_BAD_CONTENT
	| typeof ARENA_PARAMS_REFUSAL_UNANCHORED
	| typeof ARENA_PARAMS_REFUSAL_BAD_ANCHOR
	| typeof ARENA_PARAMS_REFUSAL_ANCHOR_MISMATCH
	| typeof ARENA_PARAMS_REFUSAL_SIGNER_NOT_IN_ROSTER

/** The one error type every refusal throws, carrying its stable `refusal` name. */
export class ArenaParamsError extends Error {
	readonly refusal: ArenaParamsRefusalName

	constructor(refusal: ArenaParamsRefusalName, message: string) {
		super(message)
		this.name = 'ArenaParamsError'
		this.refusal = refusal
	}
}

// =========================================================================
// Parsed shapes
// =========================================================================

/** One entry of the committed validator roster. */
export interface ArenaParamsValidator {
	pubkey: string
	name: string | null
	index: number | null
}

/**
 * The escrow terms, in the wire's own snake_case (this is the relay's document,
 * projected — not a re-mapping). **Every field is `null` when the relay did not
 * carry a usable value**: never a default, never a `0`, never an empty string.
 */
export interface ArenaParamsTerms {
	group_key: string | null
	mint_url: string | null
	keyset_id: string | null
	keys: Record<string, string> | null
	settlement_safety_sec: number | null
	bid_to_consensus_latency_sec: number | null
	min_window_sec: number | null
	max_window_sec: number | null
	/**
	 * The **effective** minimum raise the chain enforces at bid admission, in
	 * basis points of the top position (`Params.MinIncrementBps`): the required
	 * raise is `max(1, ceil(top * min_increment_bps / 10000))`. It is the one
	 * term here that is **never `null`**: the chain's default when the field is
	 * absent (an older chain, or a trimmed document) is
	 * {@link ARENA_DEFAULT_MIN_INCREMENT_BPS}, and a `0` is that default too — a
	 * chain that enforced no raise would still admit a 1-sat self-raise, which
	 * is exactly what the chain now forbids. **Not** the lot's create-time
	 * `min_increment`, which the chain does not use for the raise.
	 */
	min_increment_bps: number
	min_duration_sec: number | null
	max_duration_sec: number | null
	max_proofs: number | null
	threshold: number | null
	validators: ArenaParamsValidator[] | null
	/**
	 * The **create-content rules** the chain publishes as code (`ParamsContent`
	 * only — deliberately not on `Params`, so `params_version` does not move).
	 * The app's create pre-flight reads these rather than hardcoding a second
	 * copy of the chain's rules: a rule change on the chain reaches the form
	 * without a client edit. Every one is `null` when the relay did not carry it,
	 * and a `null` rule means the pre-flight cannot check it — never a default.
	 */
	max_title_chars: number | null
	max_description_chars: number | null
	max_image_chars: number | null
	max_category_chars: number | null
	max_name_chars: number | null
	/** The **name** of the image rule (`"same-site-or-https"`), not a pattern. `null` when unstated. */
	image_rule: string | null
	start_price_min: number | null
	start_price_max: number | null
	increment_min: number | null
	increment_max: number | null
}

export interface ParsedArenaParams {
	/** The event id — the authority this reading is keyed on. */
	eventId: string
	/** The signing validator, from the event's own pubkey. */
	signerPubkey: string
	/** The anchored height (tag and content agree). */
	height: number
	/** The anchored app hash (tag and content agree). */
	appHash: string
	/**
	 * The chain's sha256 over its canonical `Params` JSON. **Opaque**: carried to
	 * be compared ("same digest, same terms"), never recomputed from `terms`.
	 * `null` when the event omitted it.
	 */
	paramsVersion: string | null
	terms: ArenaParamsTerms
}

/** One refusal, tagged with the event it came from, for a health/counters view. */
export interface ArenaParamsRefusal {
	eventId: string
	refusal: ArenaParamsRefusalName
	detail: string
}

// =========================================================================
// Helpers
// =========================================================================

const HEX = /^[0-9a-fA-F]+$/

function tagValue(tags: readonly string[][], name: string): string | null {
	for (const tag of tags) {
		if (tag[0] === name && typeof tag[1] === 'string' && tag[1].length > 0) return tag[1]
	}
	return null
}

function parseContentObject(content: string): Record<string, unknown> {
	let parsed: unknown
	try {
		parsed = JSON.parse(content)
	} catch {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_CONTENT, 'content is not valid JSON')
	}
	if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_CONTENT, 'content JSON is not an object')
	}
	return parsed as Record<string, unknown>
}

/** A non-empty string, kept verbatim; anything else is unknown (`null`). */
function asNonEmptyString(value: unknown): string | null {
	return typeof value === 'string' && value.length > 0 ? value : null
}

/**
 * The chain's own default minimum raise, in basis points of the top position
 * (`Params.MinIncrementBps`). A params event that omits the field — an older
 * chain, or a trimmed document — means the chain is enforcing this default, so
 * the app reads the **effective** value rather than `null`: the required raise
 * is 2% of the top, rounded up, floored at 1 sat.
 */
export const ARENA_DEFAULT_MIN_INCREMENT_BPS = 200

/**
 * The effective `min_increment_bps`: a positive integer from the event, else the
 * chain's default. An absent field and a `0` both mean "the chain's default",
 * never "no raise" — a chain that enforced no raise would still admit a 1-sat
 * self-raise, which is exactly the case the chain's rule now forbids.
 */
function asMinIncrementBps(value: unknown): number {
	const bps = asCount(value)
	return bps === null || bps === 0 ? ARENA_DEFAULT_MIN_INCREMENT_BPS : bps
}

/** A non-negative integer; anything else (fraction, negative, NaN) is unknown (`null`). */
function asCount(value: unknown): number | null {
	const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : Number.NaN
	return Number.isInteger(n) && n >= 0 ? n : null
}

/** A `{ "<denomination>": "<pubkey>" }` map of non-empty strings, or `null`. */
function asKeys(value: unknown): Record<string, string> | null {
	if (typeof value !== 'object' || value === null || Array.isArray(value)) return null
	const out: Record<string, string> = {}
	for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
		if (typeof entry !== 'string' || entry.length === 0) return null
		out[key] = entry
	}
	return out
}

/** The validator roster, or `null` when any entry lacks a usable pubkey. */
function asValidators(value: unknown): ArenaParamsValidator[] | null {
	if (!Array.isArray(value)) return null
	const out: ArenaParamsValidator[] = []
	for (const entry of value) {
		if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) return null
		const record = entry as Record<string, unknown>
		const pubkey = asNonEmptyString(record.pubkey)
		if (pubkey === null) return null
		out.push({
			pubkey,
			name: asNonEmptyString(record.name),
			index: asCount(record.index),
		})
	}
	return out
}

function requireSchema(content: Record<string, unknown>): void {
	if (content.schema !== ARENA_PARAMS_SCHEMA) {
		throw new ArenaParamsError(
			ARENA_PARAMS_REFUSAL_BAD_SCHEMA,
			`content.schema must be ${JSON.stringify(ARENA_PARAMS_SCHEMA)}, got ${JSON.stringify(content.schema)}`,
		)
	}
}

/**
 * The mandatory anchor, verifying the tag copy **against** the content copy.
 *
 * The chain's own `ParseParamsEvent` refuses a params event whose `(height,
 * hash)` tags disagree with its `(height, app_hash)` content, so a relay cannot
 * re-frame one and hide the other. A value missing from **both** sources is
 * `unanchored` (the client MUST ignore it); present-but-malformed is
 * `bad_anchor`; present on both sides but **unequal** is `anchor_mismatch`.
 */
function requireAgreeingAnchor(tags: string[][], content: Record<string, unknown>): { height: number; hash: string } {
	const tagHeight = tagValue(tags, 'height')
	const tagHash = tagValue(tags, 'hash')
	const contentHeight = typeof content.height === 'number' ? String(content.height) : asNonEmptyString(content.height)
	const contentHash = asNonEmptyString(content.app_hash)

	if (tagHeight === null && contentHeight === null) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_UNANCHORED, 'params event is missing the mandatory height anchor')
	}
	if (tagHash === null && contentHash === null) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_UNANCHORED, 'params event is missing the mandatory hash anchor')
	}

	const height = asCount(tagHeight ?? contentHeight)
	if (height === null || height <= 0) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_ANCHOR, 'params height anchor is not a positive integer')
	}
	const hash = tagHash ?? contentHash
	if (hash === null || !HEX.test(hash)) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_ANCHOR, 'params hash anchor is not a non-empty hex string')
	}

	// The tag and content copies are the same fact written twice; a disagreement
	// means the event addresses two chain states and neither reading is safe.
	if (contentHeight !== null && String(height) !== contentHeight.trim()) {
		throw new ArenaParamsError(
			ARENA_PARAMS_REFUSAL_ANCHOR_MISMATCH,
			`tag height ${JSON.stringify(tagHeight)} != content height ${JSON.stringify(contentHeight)}`,
		)
	}
	if (contentHash !== null && tagHash !== null && contentHash.toLowerCase() !== tagHash.toLowerCase()) {
		throw new ArenaParamsError(
			ARENA_PARAMS_REFUSAL_ANCHOR_MISMATCH,
			`tag hash ${JSON.stringify(tagHash)} != content app_hash ${JSON.stringify(contentHash)}`,
		)
	}

	return { height, hash: hash.toLowerCase() }
}

/** The schnorr check, at the same parse boundary the verdict path verifies at. */
function requireVerifiedSignature(event: ArenaParamsEventLike): void {
	if (typeof event.sig !== 'string' || event.sig.length === 0) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_SIGNATURE, 'params event carries no signature')
	}
	let verified = false
	try {
		verified = verifyNostrEventSignature({
			id: event.id,
			pubkey: event.pubkey,
			kind: event.kind,
			created_at: event.created_at,
			tags: event.tags,
			content: event.content,
			sig: event.sig,
		} as Parameters<typeof verifyNostrEventSignature>[0])
	} catch {
		verified = false
	}
	if (!verified) throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_SIGNATURE, 'params event signature does not verify')
}

// =========================================================================
// The parser — one event in, one parsed params or one named refusal out
// =========================================================================

/**
 * Parse one kind-1448 params event, verifying it the way the verdict path
 * verifies a kind-1445 verdict: **signature first** (fail closed on
 * unauthenticated content), then the schema, then the mandatory agreeing
 * anchor, then roster membership.
 */
export function parseArenaParamsEvent(event: ArenaParamsEventLike): ParsedArenaParams {
	if (event.kind !== ARENA_PARAMS_KIND) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_BAD_KIND, `expected kind ${ARENA_PARAMS_KIND}, got ${event.kind}`)
	}
	requireVerifiedSignature(event)

	const content = parseContentObject(event.content)
	requireSchema(content)
	const anchor = requireAgreeingAnchor(event.tags, content)

	// The `p` tag and the event pubkey are the same signer written twice; a
	// disagreement means the event names a signer it was not signed by.
	const pTag = tagValue(event.tags, 'p')
	if (pTag !== null && pTag.toLowerCase() !== event.pubkey.toLowerCase()) {
		throw new ArenaParamsError(
			ARENA_PARAMS_REFUSAL_BAD_CONTENT,
			`p tag ${JSON.stringify(pTag)} != event pubkey ${JSON.stringify(event.pubkey)}`,
		)
	}

	const validators = asValidators(content.validators)
	// Roster membership: the signer must be a validator the committed roster
	// names. An absent/unreadable roster cannot confirm any signer, so it is a
	// refusal, not a pass.
	const signer = event.pubkey.toLowerCase()
	if (validators === null || !validators.some((validator) => validator.pubkey.toLowerCase() === signer)) {
		throw new ArenaParamsError(ARENA_PARAMS_REFUSAL_SIGNER_NOT_IN_ROSTER, `signer ${event.pubkey} is not on the committed validator roster`)
	}

	return {
		eventId: event.id ?? '',
		signerPubkey: event.pubkey,
		height: anchor.height,
		appHash: anchor.hash,
		paramsVersion: asNonEmptyString(content.params_version),
		terms: {
			group_key: asNonEmptyString(content.group_key),
			mint_url: asNonEmptyString(content.mint_url),
			keyset_id: asNonEmptyString(content.keyset_id),
			keys: asKeys(content.keys),
			settlement_safety_sec: asCount(content.settlement_safety_sec),
			bid_to_consensus_latency_sec: asCount(content.bid_to_consensus_latency_sec),
			min_window_sec: asCount(content.min_window_sec),
			max_window_sec: asCount(content.max_window_sec),
			min_increment_bps: asMinIncrementBps(content.min_increment_bps),
			min_duration_sec: asCount(content.min_duration_sec),
			max_duration_sec: asCount(content.max_duration_sec),
			max_proofs: asCount(content.max_proofs),
			threshold: asCount(content.threshold),
			validators,
			max_title_chars: asCount(content.max_title_chars),
			max_description_chars: asCount(content.max_description_chars),
			max_image_chars: asCount(content.max_image_chars),
			max_category_chars: asCount(content.max_category_chars),
			max_name_chars: asCount(content.max_name_chars),
			image_rule: asNonEmptyString(content.image_rule),
			start_price_min: asCount(content.start_price_min),
			start_price_max: asCount(content.start_price_max),
			increment_min: asCount(content.increment_min),
			increment_max: asCount(content.increment_max),
		},
	}
}

/** A refusal predicate, for the edge that must "ignore, not merely distrust". */
export function isVerifiedArenaParamsEvent(event: ArenaParamsEventLike): boolean {
	try {
		parseArenaParamsEvent(event)
		return true
	} catch {
		return false
	}
}

// =========================================================================
// The selection — the newest anchored reading wins
// =========================================================================

export interface ArenaParamsSelection {
	/** The newest valid, anchored reading, or `null` when none arrived. */
	params: ParsedArenaParams | null
	/** Every event that was refused, with its stable name — never silently dropped. */
	refusals: ArenaParamsRefusal[]
}

/**
 * Reduce a set of params events to the newest **anchored** reading.
 *
 * Each event is parsed (and refused by name if it fails); the survivors are
 * ordered by **anchored height descending**, then `created_at` descending, then
 * the lexically lowest event id — so the live chain's reading (height 344+)
 * always beats a foreign test chain's (height 2 / 20), and two chain states at
 * different heights are always ordered by the chain, not by relay arrival.
 * Deduped by event id first, because two relays can only agree on an id.
 */
export function selectNewestArenaParams(events: readonly ArenaParamsEventLike[]): ArenaParamsSelection {
	const byId = new Map<string, ArenaParamsEventLike>()
	for (const event of events) {
		if (typeof event?.id === 'string' && event.id.length > 0) byId.set(event.id, event)
	}

	const refusals: ArenaParamsRefusal[] = []
	const parsed: ParsedArenaParams[] = []
	for (const event of byId.values()) {
		try {
			parsed.push(parseArenaParamsEvent(event))
		} catch (error) {
			if (error instanceof ArenaParamsError) {
				refusals.push({ eventId: event.id, refusal: error.refusal, detail: error.message })
			} else {
				throw error
			}
		}
	}

	if (parsed.length === 0) return { params: null, refusals }

	const newest = parsed.reduce((best, candidate) => {
		if (candidate.height !== best.height) return candidate.height > best.height ? candidate : best
		const candidateAt = byId.get(candidate.eventId)?.created_at ?? 0
		const bestAt = byId.get(best.eventId)?.created_at ?? 0
		if (candidateAt !== bestAt) return candidateAt > bestAt ? candidate : best
		return candidate.eventId.localeCompare(best.eventId) < 0 ? candidate : best
	})

	return { params: newest, refusals }
}

// =========================================================================
// The read (transport)
// =========================================================================

const DEFAULT_DEADLINE_MS = 8000

export interface ArenaParamsReadInit {
	/** The app's read context, over whatever transport the host configured. */
	context: EventReadContext<NostrEventLike>
	/** Per-read deadline in ms. A read resolves with what arrived; it never rejects on the network. */
	deadlineMs?: number
}

/**
 * Read the escrow's terms: subscribe to kind 1448, collect to caught-up (or the
 * deadline), and keep the newest anchored reading. A read that delivered nothing
 * usable resolves with `params: null` — the caller refuses; it never reaches for
 * an HTTP fallback.
 */
export async function readArenaParams(init: ArenaParamsReadInit): Promise<ArenaParamsSelection> {
	const controller = new AbortController()
	const timer = setTimeout(() => controller.abort(), init.deadlineMs ?? DEFAULT_DEADLINE_MS)
	const filters: EventFilter[] = [{ kinds: [ARENA_PARAMS_KIND] }]
	const byId = new Map<string, ArenaParamsEventLike>()
	try {
		for await (const item of init.context.stream(filters, { signal: controller.signal, bounded: true })) {
			if (item.type !== 'event') break
			const event = item.event as unknown as ArenaParamsEventLike
			if (typeof event.id === 'string' && event.id.length > 0) byId.set(event.id, event)
		}
	} catch {
		// A relay that fails mid-stream is health, not a throw: answer with what
		// arrived. `params: null` then says honestly that nothing usable came.
	} finally {
		clearTimeout(timer)
	}
	return selectNewestArenaParams([...byId.values()])
}

// =========================================================================
// The web host's wiring — the only part that touches a transport
// =========================================================================

export interface WebArenaParamsReadInit {
	/** Every relay to read from; typically `webRelayPolicy('query')`. */
	relays: readonly string[]
	/** The shared event store, as the app's read context composes it. */
	store: EventStorePort<Event>
	deadlineMs?: number
}

/**
 * The production read: a one-shot `ArenaParamsSelection` fetch over the SDK's
 * read seam (via `platform/web/sdkNostrIo.ts` → `sdk/core/nostr-io`). Called
 * fresh at each bid, because `group_key` is regenerated by `arena init` and a
 * cached key would strand the escrow.
 */
export function createWebArenaParamsRead(init: WebArenaParamsReadInit): () => Promise<ArenaParamsSelection> {
	const context = createWebRelayReadContext(init.store, init.relays, {
		deadlineMs: init.deadlineMs ?? DEFAULT_DEADLINE_MS,
	})
	return () => readArenaParams({ context, deadlineMs: init.deadlineMs })
}
